    /**
     * Seed 3 mata pelajaran, masing-masing 150 soal dengan 5 pilihan jawaban (A–E).
     */
    public function run(): void
    {
        $subjects = [
            [
                'name'        => 'Pemrograman Web',
                'description' => 'Mata pelajaran yang membahas dasar-dasar pemrograman web, meliputi HTML, CSS, JavaScript, dan framework modern.',
                'is_active'   => true,
            ],
            [
                'name'        => 'Basis Data',
                'description' => 'Mata pelajaran yang membahas konsep dan implementasi basis data relasional, SQL, normalisasi, dan manajemen sistem basis data.',
                'is_active'   => true,
            ],
            [
                'name'        => 'Jaringan Komputer',
                'description' => 'Mata pelajaran yang membahas konsep jaringan komputer, protokol komunikasi, topologi, keamanan jaringan, dan troubleshooting.',
                'is_active'   => true,
            ],
        ];

        foreach ($subjects as $subjectData) {
            $subject = Subject::create($subjectData);
            $this->seedQuestions($subject);
        }
    }

    private function seedQuestions(Subject $subject): void
    {
        $questions = $this->getQuestionsFor($subject->name);
        $count = count($questions);

        // Jika kurang dari 150, pad hingga 150 soal
        $faker = \Faker\Factory::create('id_ID');
        for ($i = $count + 1; $i <= 150; $i++) {
            $correctLetter = $faker->randomElement(['A', 'B', 'C', 'D', 'E']);
            $questions[] = [
                'payload'        => "[$subject->name] Soal nomor {$i}: Berapa nilai evaluasi parameter optimasi sistem ke-{$i}?",
                'correct_answer' => $correctLetter,
                'description'    => "Penjelasan analisis untuk soal nomor {$i} pada mata pelajaran {$subject->name}.",
                'answers'        => [
                    'A' => "Opsi A untuk soal {$i} ({$subject->name})",
                    'B' => "Opsi B untuk soal {$i} ({$subject->name})",
                    'C' => "Opsi C untuk soal {$i} ({$subject->name})",
                    'D' => "Opsi D untuk soal {$i} ({$subject->name})",
                    'E' => "Opsi E untuk soal {$i} ({$subject->name})",
                ],
            ];
        }

        foreach ($questions as $qData) {
            $question = Question::create([
                'subject_id'     => $subject->id,
                'payload'        => $qData['payload'],
                'correct_answer' => $qData['correct_answer'],
                'description'    => $qData['description'] ?? null,
                'is_active'      => true,
            ]);

            // buat 5 pilihan jawaban A–E untuk setiap soal
            foreach ($qData['answers'] as $letter => $text) {
                Answer::create([
                    'question_id' => $question->id,
                    'letter'      => $letter,
                    'text'        => $text,
                    'is_active'   => true,
                ]);
            }
        }
    }

