    private function getQuestionsFor(string $subjectName): array
    {
        return match (true) {
            str_contains($subjectName, 'Pemrograman') => $this->getPemrogramanWebQuestions(),
            str_contains($subjectName, 'Basis')       => $this->getBasisDataQuestions(),
            str_contains($subjectName, 'Jaringan')    => $this->getJaringanKomputerQuestions(),
            default                                    => [],
        };
    }
